def calc_letter_inf(letter: str, ix, iy, textSize, yoff, font_name):

    try:
        letter_info = fm.get_letter_info(letter, font_name, textSize)

        _xadvance = letter_info['width']
        if letter in '《（）》'+'AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz1234567890':
            _xadvance = letter_info['width']
        if letter in '，。！？':
            _xadvance = textSize*0.7

        _xoffset = 0
        _yoffset = int(letter_info['yoffset']+yoff)

        if letter == ' ':
            letter_info['width'] = 1
            letter_info['height'] = 1
            _xadvance = 1
            _start_x = ix*textSize + 2*(ix+1)
            _start_y = iy*textSize + 2*iy
            _end_x = int(_start_x+letter_info['width'])
            _end_y = int(_start_y+letter_info['height'])
        else:
            _start_x = ix*textSize+2*(ix) # +int(letter_info['xoffset'])
            if font_name == 'font':
                _start_x -= 1
            _start_y = iy*textSize-1 + (2*iy)  # +int(letter_info['yoffset'])

            _end_x = int(_start_x+letter_info['width']) + 2
            _end_y = int(_start_y+letter_info['height']) + 2

        return pack('<f3H3h4H', 0,
                    ord(letter),
                    int(letter_info['width']),
                    int(letter_info['height']),
                    int(_xadvance),
                    _xoffset,
                    _yoffset,
                    max(_start_x, 0) * 16,
                    max(_start_y, 0) * 16,
                    _end_x * 16,
                    _end_y * 16
                    ), font_name
    except AttributeError as e:
        # return calc_letter_inf(letter, ix, iy,textSize,yoff)
        failed.append(f"[{font_name}]{repr(letter)} Cause {e}")
        return b'', font_name
    except TypeError as e:
        # return calc_letter_inf(letter, ix, iy,textSize,yoff)
        if font_name != '微软雅黑':
            failed.append(
                f"[{font_name}]{repr(letter)} Using 微软雅黑 cause letter doesn't exist.")
            return calc_letter_inf(letter, ix, iy, textSize, yoff, '微软雅黑')
        failed.append(
            f"[{font_name}]{repr(letter)} Cause letter doesn't exist.")
        return b'', font_name
    except Exception as e:
        print('unknow magic')


def _char(_hex):
    _ = _hex[:4].decode()
    return chr(int((_[2:4]+_[:2]), 16))


