def _int(value):
    return pack('<H', value).decode()


def long_int(value):
    return pack('<f', value).decode()


def generate(infname, info):
    shape = info['resolution']
    textSize = info['tsize']
    font_name = ''.join(infname.split('_')[1:]).split('.')[0]

    letter_inf = [a2b_hex(info['head'].replace(' ', ''))]  # FFN头部
    generate_png = numpy.zeros([*shape, 4], dtype=numpy.uint8)  # TG4尺寸
    letters_count = 0

    # 读取原版
    with open(f'data/ds2ORIGIN/{infname}', 'rb') as origin_inf_file:
        origin_inf_content = origin_inf_file.read()
    origin_inf_content = b2a_hex(origin_inf_content)
    ep = unpack('H', a2b_hex(origin_inf_content[128:132]))[0] * 2
    _ = re.findall('.{48}', origin_inf_content[2208:ep].decode())
    origin_inf_letters = [a[8:]
                          for a in _ if int(a[8:], 16)]  # and not int(a[:8],16)
    origin_letters = [a2b_hex(_[:4]) for _ in origin_inf_letters]
    origin_png = cv2.imread(f"data/ds2ORIGIN/{info['png']}", -1)
    if info.get('use_origin'):
        _letters = [l for l in letters if pack(
            'H', ord(l)) not in origin_letters]
        generate_png[0:origin_png.shape[0], 0:origin_png.shape[1]] = origin_png

        for _ in origin_inf_letters:
            if _.startswith('2000'):
                _ = _[:12]+'01'+_[14:]
            letter_inf.append(a2b_hex('00000000'+_))
        letters_count += len(origin_inf_letters)
    else:
        _letters = letters

    failed_letters = []
    line, index = 0, 0
    for letter in tqdm(_letters, f'Generating {font_name}', leave=False):
        if info['use_origin']:
            letter_using_font = info['font4chinese']
        elif pack('H', ord(letter)) in origin_letters:  # 原版字符
            letter_using_font = info['font4origin']
        else:
            letter_using_font = info['font4chinese']

        # if info['font4chinese'] == 'font':
        #     letter_using_font = '微软雅黑'

        while True:  # 确定渲染位置
            x = textSize * index + (index *2)
            y = textSize * line + (line*2)

            if x+textSize > info['resolution'][1]:
                index = 0
                line += 1
                continue

            if info.get('use_origin') and y < origin_png.shape[0] and x < origin_png.shape[1]:
                index += 1
                continue

            index += 1
            break

        letters_count += 1
        _, font_name = calc_letter_inf(letter, index-1, line, textSize,
                                       info['yoffset'], letter_using_font)
        if _ != b'':
            letter_inf.append(_)
            generate_png = letter_render(
                generate_png, letter, (x, y), textSize, font_name)
        else:
            letters_count -= 1
            index -= 1

        if letters_count >= 2348:
            break

    end_position = len(b''.join(letter_inf))
    letter_inf.append(b'\x00'*(0x4E078 - end_position))
    letter_inf.append(a2b_hex(info['tail'].replace(' ', '')))
    # 修改信息
    _ = letter_inf[0]
    _ = _[:4]+pack('<i', len(b''.join(letter_inf)))+_[8:]
    _ = _[:10]+pack('<H', letters_count)+_[12:]  # 字符数
    _ = _[:64]+pack('<H', end_position+4)+_[66:]  # 替换补全起点
    letter_inf[0] = _

    # _ = b2a_hex(letter_inf[0]).decode()
    # letter_inf[0] = a2b_hex(_[:20]+_int(letters_count)+_[24:])
    # _ = b2a_hex(letter_inf[0]).decode()
    # letter_inf[0] = a2b_hex(_[:128]+_int(end_position+4)+_[132:])  # 替换补全起点
    # _ = b2a_hex(letter_inf[0]).decode()
    # print(f'filesize: {len(b"".join(letter_inf))}')
    # letter_inf[0] = a2b_hex(_[:8]+long_int(len(b''.join(letter_inf))/2)+_[16:])  # 文件大小

    cv2.imwrite(info['png'], pil2cv(generate_png))  # 导出png
    generate_tg4d(info['png'])  # 导出tg4d
    with open(f'ds2output/FFN/{infname}', 'wb') as f:
        f.write(b''.join(letter_inf))  # 导出inf


